export function translateText(value, language) {
  if (typeof value !== 'string' || language === 'en') return value;
  const sharedIndex = languageOrder.indexOf(language);
  const exactCopy = language === 'hi'
    ? Object.entries(hindiCopy).find(([source]) => source.toLowerCase() === value.trim().toLowerCase())?.[1]
    : undefined;
  if (exactCopy) return exactCopy;
  const replacePhrase = (text, source, translated) => {
    if (!translated || translated === source) return text;
    const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return text.replace(new RegExp(`(^|[^\\p{L}\\p{N}])(${escaped})(?=$|[^\\p{L}\\p{N}])`, 'giu'), (_, lead) => `${lead}${translated}`);
  };
  let result = value;
  for (const [source, translations] of Object.entries(sharedLabels).sort(([a], [b]) => b.length - a.length)) {
    result = replacePhrase(result, source, translations[sharedIndex]);
  }
  for (const [source, translations] of Object.entries(sharedCopy).sort(([a], [b]) => b.length - a.length)) {
    result = replacePhrase(result, source, translations[sharedIndex]);
  }
  const exact = commonTranslations[language]?.[value];
  if (exact && exact !== value) return exact;
  result = phraseEntries.reduce((text, source) => {
    const translated = commonTranslations[language]?.[source];
    return replacePhrase(text, source, translated);
  }, result);
  if (language === 'hi') {
    for (const [source, translated] of Object.entries(hindiCopy).sort(([a], [b]) => b.length - a.length)) {
      result = replacePhrase(result, source, translated);
    }
  }
  return result;
}
